"use strict";
// Loads its formatter by a computed specifier while the module evaluates:
// the package runs in a Node island. It exports an object with a
// function, a class and a counter.
var util = require(["ut", "il"].join(""));
var stock = { salt: 500, rice: 2000, flour: 1000 };
var lookups = 0;

class Jar {
  constructor(label, count) {
    this.label = label;
    this.count = count;
  }
  describe() {
    return util.format("%dx%s", this.count, this.label);
  }
}

exports.Jar = Jar;
exports.find = function find(name) {
  lookups++;
  if (!Object.prototype.hasOwnProperty.call(stock, name)) {
    throw new RangeError("nothing called " + name);
  }
  return { label: name.toUpperCase(), grams: stock[name] };
};
exports.lookups = function () {
  return lookups;
};
